examples.code:
[X, Y] = meshgrid(linspace(-2, 2, 40));
Z = X .* exp(-X.^2 - Y.^2);
surf(X, Y, Z)
xlabel('x')
ylabel('y')
zlabel('z')

[X, Y] = meshgrid(-3:0.25:3);
Z = sin(sqrt(X.^2 + Y.^2));
surf(X, Y, Z, 'FaceAlpha', 0.6, 'EdgeColor', 'none')
view(30, 60)

[X, Y] = meshgrid(linspace(-8, 8, 41));
R = sqrt(X.^2 + Y.^2) + eps;
mesh(X, Y, sin(R) ./ R)

[X, Y] = meshgrid(linspace(-2, 2, 60));
Z = X.^2 + 2*Y.^2;
[C, h] = contour(X, Y, Z, [0.5 1 2 4]);
clabel(C, h)
axis equal

[X, Y] = meshgrid(linspace(-3, 3, 80));
Z = peaks(X, Y);
contourf(X, Y, Z, 15)
colorbar
axis equal tight

rng default
X = randn(200, 5);
X(:, 2) = X(:, 1) + 0.5*X(:, 2);
X(:, 4) = -X(:, 3) + 0.3*X(:, 4);
imagesc(corrcoef(X), [-1 1])
colorbar
axis square

[X, Y] = meshgrid(-2:0.4:2);
quiver(X, Y, -Y, X)
axis equal

[X, Y] = meshgrid(linspace(-2, 2, 20));
Z = X .* exp(-X.^2 - Y.^2);
[DX, DY] = gradient(Z, X(1, 2) - X(1, 1));
contour(X, Y, Z, 15)
hold on
quiver(X, Y, DX, DY, 'k')
hold off
axis equal
